  let mean = 0, m2 = 0, min = Infinity, max = -Infinity;
  values.forEach((v, i) => { const delta = v - mean; mean += delta / (i + 1); m2 += delta * (v - mean); min = Math.min(min, v); max = Math.max(max, v); });
