oFixed(3)} s · publisher annotation`} onClick={() => marker(e)}/>)}</div></div><label className="speed-control"><span className="sr-only">Playback speed</span><select aria-label="Playback speed" value={replay.speed} onChange={e => replay.setSpeed(Number(e.target.value))}>{[.5,1,2,4].map(n => <option key={n} value={n}>{n}×</option>)}</select></label><span className="play-state">{replay.playing ? 'Playing' : 'Paused'}</span></footer>
