.visual-tabs button { background: none; border: 0; border-bottom: 2px solid transparent; padding: 0 1px; color: var(--quiet); }
.visual-tabs button[aria-pressed="true"] { color: var(--accent); border-bottom-color: var(--accent); }
.visual-workspace .recording-context { height: auto; min-height: 180px; flex: 1.2 1 0; }
