.conversation { padding: 24px; overflow-anchor: none; overscroll-behavior: contain; }
.conversation-intro { padding-block: 24px; max-width: 44ch; }
.conversation-intro > svg { color: var(--accent); margin-bottom: 20px; }
.conversation-intro h3 { font-size: 24px; line-height: 1.3; font-weight: 450; text-wrap: balance; }
.conversation-intro > p { display: block; margin-top: 16px; font-size: 14px; line-height: 1.8; }
.conversation-intro .intro-limit { font-size: 12px; margin-top: 24px; }
.conversation-turn { margin-bottom: 28px; }
.user-question { padding-bottom: 14px; margin-bottom: 22px; }
.user-question p { font-size: 14px; font-weight: 500; }
.user-question small { font-size: 11px; }
.assistant-answer { display: block; }
.prediction-summary h3 { font-size: 23px; line-height: 1.35; font-weight: 500; letter-spacing: -.02em; }
.prediction-facts { display: grid; gap: 6px; margin-top: 16px; color: var(--quiet); font-size: 13px; }
.prediction-facts strong { color: var(--text); font-weight: 500; }
.assistant-answer .prediction-caution { font-size: 12px; color: var(--quiet); line-height: 1.6; margin-top: 14px; }
.measured-summary { margin-top: 28px; }
.measured-summary h3 { font-size: 13px; font-weight: 500; margin-bottom: 8px; }
.measured-summary p { color: #c5ced1; }
.review-note { margin-top: 18px; padding: 11px 13px; border-left: 2px solid var(--amber); background: #211f1b; }
.review-note h3 { margin-bottom: 5px; color: #d8bc91; font-size: 11px; font-weight: 500; letter-spacing: .04em; text-transform: uppercase; }
.review-note p { color: #cfc7b9; font-size: 12px; line-height: 1.55; }
.answer-brief section { border: 0; padding: 0; margin-top: 20px; }
.answer-brief h3 { text-transform: none; letter-spacing: 0; }
.evidence-links { margin-top: 18px; }
.evidence-links button { min-height: 34px; }
.input-receipt { margin-top: 18px; font-size: 12px; color: var(--quiet); overflow-wrap: anywhere; }
.input-receipt summary { cursor: pointer; padding-block: 5px; }
.input-receipt pre { white-space: pre-wrap; overflow-wrap: anywhere; max-height: 240px; overflow-y: auto; font-size: 11px; }
.input-receipt > p { margin-block: 10px; font-size: 12px; }
.report-export { margin-top: 8px; }
.composer { margin: 10px 24px 20px; border-color: var(--line); background: #202628; }
.composer textarea { min-height: 44px; height: 44px; font-size: 14px; padding-top: 12px; }
.composer .mode-select select { font-size: 12px; }
.selection-footer { height: 38px; flex-shrink: 0; }
.selection-footer > .text-button { margin-left: auto; }
@media (min-width: 851px) and (max-width: 1100px) {
  .inspect-grid { grid-template-columns: minmax(350px, .9fr) minmax(400px, 1.1fr); }
  .model-input-status, .assistant-panel > .panel-heading, .conversation { padding-inline: 18px; }
  .composer { margin-inline: 18px; }
}
@media (max-width: 850px) {
  .app-shell { height: 100dvh; min-height: 0; overflow: hidden; padding-bottom: 115px; }
  .app-header { height: 54px; padding-inline: 14px; }
  .app-body { min-height: 0; }
  .demo-cases { min-height: 60px; padding: 9px 14px; gap: 8px; flex-wrap: wrap; }
  .demo-cases label { gap: 8px; font-size: 12px; }
  .demo-cases select { min-width: 0; max-width: 230px; font-size: 16px; padding: 6px; }
  .case-source { margin-left: 0; font-size: 11px; }
  .case-source p { left: 0; right: auto; }
  .inspect-grid { min-height: 0; overflow: hidden; }
  .mobile-signals .left-workspace, .mobile-assistant .visual-workspace { display: none; }
  .mobile-assistant .left-workspace { height: 100%; min-height: 0; flex: 1; }
  .mobile-assistant .assistant-panel { height: auto; min-height: 0; flex: 1; }
  .visual-workspace { height: 100%; flex: 1; }
  .visual-workspace .recording-context { display: flex; min-height: 160px; flex: 1.2 1 0; }
  .visual-workspace .signals-panel { display: flex; min-height: 160px; flex: 1 1 0; }
  .visual-tabs { height: 42px; padding-inline: 16px; gap: 20px; font-size: 12px; }
  .visual-signals .signals-panel { min-height: 0; }
  .visual-signals .signal-strips { overflow-y: auto; }
  .visual-signals .signal-strip { min-height: 56px; }
  .visual-workspace .event-browser { width: 135px; }
  .robot-caption { padding-inline: 12px; height: 38px; }
  .robot-footer { padding-inline: 12px; font-size: 10px; }
  .robot-joints { padding-top: 4px; }
  .robot-joints button { height: 23px; }
  .assistant-panel > .panel-heading { height: 42px; padding-inline: 18px; }
  .model-input-status { padding: 14px 18px; gap: 8px; }
  .model-input-status strong { font-size: 13px; }
  .model-input-status span { font-size: 11px; }
  .model-input-status .btn { font-size: 12px; }
  .conversation { padding: 20px 18px; }
  .conversation-intro { padding-block: 10px; }
  .conversation-intro h3, .prediction-summary h3 { font-size: 22px; }
  .conversation-intro > p { font-size: 14px; }
  .composer { margin: 8px 14px 14px; }
  .composer textarea { font-size: 16px; }
  .selection-footer { height: 38px; }
  .selection-footer .text-button { font-size: 10px; }
  .transport { bottom: 38px; }
}

/* Event time is explicit; the robot remains measured context, not a contact reconstruction. */
.robot-event-cue { min-height: 62px; padding: 9px 14px; display: flex; flex-direction: column; justify-content: center; gap: 4px; border-bottom: 1px solid var(--line); background: #1b2225; }
.robot-event-cue strong { font-size: 12px; font-weight: 600; }
.robot-event-cue span { font-size: 11px; color: #b6c2c5; line-height: 1.4; max-width: 70ch; }
.robot-event-cue.at-onset { background: #342d22; }
.robot-event-cue.at-onset strong { color: #f0d4a5; }
.robot-event-cue.at-onset span { color: #deceb8; }
.robot-prediction-action { margin: 4px 0 12px; }
.visual-tabs .replay-interval { margin-left: auto; }
@media(max-width:850px) { .robot-event-cue { min-height: 72px; padding: 8px 10px; } }

/* The data page follows one sourcing path and keeps replay-only controls out of view. */
.view-data .main-workspace,.view-evaluation .main-workspace{overflow:hidden}
.view-data .secondary-view,.view-evaluation .secondary-view{padding:22px 32px 42px;scroll-behavior:smooth}
.view-data .back-inspect,.view-evaluation .back-inspect{margin-bottom:12px}
.header-right .btn[aria-pressed=true]{color:var(--accent);border-color:#587165;background:#24302b}
.data-heading{margin-bottom:8px;padding-bottom:12px;border-bottom:0}
.data-heading>svg,.view-data .section-heading>svg{color:var(--quiet)}
.view-data .candidate-role{color:var(--quiet)!important}
.recording-summary,.catalog-summary{margin-bottom:28px;border-bottom:1px solid var(--line)}
.recording-summary>summary,.catalog-summary>summary{display:flex;align-items:center;justify-content:space-between;gap:18px;list-style:none;cursor:pointer;padding:13px 0;color:var(--text)}
.recording-summary>summary::-webkit-details-marker,.catalog-summary>summary::-webkit-details-marker{display:none}
.recording-summary>summary>span,.catalog-summary>summary>span{display:flex;align-items:baseline;gap:12px;min-width:0;color:#c8d1d3}
.recording-summary>summary strong,.catalog-summary>summary strong{font-size:12px;font-weight:500;color:var(--text);white-space:nowrap}
.recording-summary>summary small,.catalog-summary>summary small{color:var(--quiet);font-size:10px;text-align:right}
.recording-summary>summary::after,.catalog-summary>summary::after{content:'+';order:3;color:var(--quiet);font-size:16px;line-height:1}
.recording-summary[open]>summary::after,.catalog-summary[open]>summary::after{content:'−'}
.recording-details,.catalog-details{padding:4px 0 20px}
.recording-details>p:first-child{color:var(--quiet);font-size:12px;line-height:1.6}
.dataset-scout{padding-top:2px}
.dataset-scout .section-heading h2,.ingestion-handoff .section-heading h2{font-size:18px;margin-bottom:0}
.dataset-scout>label,.ingestion-handoff>form>label{display:block;margin-top:18px;color:#cbd4d6;font-size:12px}
.source-ready{display:flex;align-items:center;gap:7px;margin:14px 0 0;color:var(--accent);font-size:12px}
.ingestion-handoff{scroll-margin-top:18px}
.ingestion-handoff>form .field-row{margin-top:7px}
.ingestion-handoff>form input{min-width:320px}
.ingestion-progress{margin-top:18px;padding-top:18px;border-top:1px solid var(--line)}
.ingestion-progress h3{font-size:12px!important;margin-bottom:10px!important}
.ingestion-stages{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;margin:0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.ingestion-stages li{gap:8px;padding:10px 12px;border-right:1px solid var(--line);font-size:10px;line-height:1.4}
.ingestion-stages li:first-child{padding-left:0}
.ingestion-stages li:last-child{border-right:0}
.ingestion-stages li>span{width:6px;height:6px;border:1px solid #667177;border-radius:50%;flex:0 0 auto}
.catalog-details>label{display:block;margin:4px 0 7px;color:var(--quiet);font-size:11px}
.catalog-details>select{min-width:260px;background:#20282c;border:1px solid #45535a;border-radius:4px;color:var(--text);padding:8px 10px}

@media(max-width:850px){
  .app-shell.view-data,.app-shell.view-evaluation{height:100dvh;min-height:0;overflow:hidden;padding-bottom:0}
  .view-data .app-body,.view-evaluation .app-body{min-height:0}
  .view-data .secondary-view,.view-evaluation .secondary-view{padding:14px 16px 32px}
  .recording-summary>summary,.catalog-summary>summary{align-items:flex-start;flex-wrap:wrap;gap:5px 10px;padding:12px 0}
  .recording-summary>summary>span,.catalog-summary>summary>span{align-items:flex-start;flex-direction:column;gap:2px;max-width:calc(100% - 30px)}
  .recording-summary>summary small,.catalog-summary>summary small{width:100%;order:4;text-align:left}
  .dataset-scout .section-heading h2,.ingestion-handoff .section-heading h2{font-size:17px}
  .ingestion-handoff>form input{min-width:0}
  .ingestion-stages{grid-template-columns:1fr 1fr}
  .ingestion-stages li:nth-child(2){border-right:0}
  .ingestion-stages li:nth-child(-n+2){border-bottom:1px solid var(--line)}
}

/* Audited evaluation page: pipeline-backed numbers with visible denominators. */
.evaluation-heading{margin-bottom:10px;padding-bottom:18px}
.evaluation-heading>svg,.evaluation-content .section-heading>svg,.evaluation-chart svg{color:var(--quiet)}
.evaluation-conclusion{display:flex;gap:11px;align-items:flex-start;padding:15px 0;border-bottom:1px solid var(--line)}
.evaluation-conclusion>svg{color:var(--accent);margin-top:2px}
.evaluation-conclusion strong{font-size:14px;font-weight:500}
.evaluation-conclusion p{max-width:850px;margin-top:3px;color:var(--quiet);font-size:12px;line-height:1.6}
.evaluation-summary{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:0!important;margin:0 0 28px!important;border-bottom:1px solid var(--line)}
.evaluation-summary>div{padding:16px 18px;border-right:1px solid var(--line)}
.evaluation-summary>div:first-child{padding-left:0}
.evaluation-summary>div:last-child{border-right:0}
.evaluation-summary dt{font-size:10px!important}
.evaluation-summary dd{margin:3px 0 0!important;font:500 23px 'IBM Plex Mono',monospace;color:var(--text)}
.evaluation-summary small{color:var(--quiet);font-size:10px}
.evaluation-summary.evaluation-summary-four{grid-template-columns:repeat(4,minmax(0,1fr))!important}
.evaluation-chart-grid{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin-bottom:32px}
.evaluation-chart{min-width:0}
.chart-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding-bottom:10px;border-bottom:1px solid var(--line)}
.chart-heading h2{font-size:15px}
.chart-heading p{margin-top:3px;color:var(--quiet);font-size:10px}
.evaluation-legend{display:flex;gap:13px;flex-wrap:wrap;padding:10px 0;color:var(--quiet);font-size:9px}
.evaluation-legend span{display:flex;align-items:center;gap:5px}
.method-color{display:block;width:7px;height:7px}
.method-color.method-features,.metric-track .method-features{background:var(--accent)}
.method-color.method-cnn,.metric-track .method-cnn{background:#76a6c4}
.method-color.method-opentslm,.metric-track .method-opentslm{background:#82aeca}
.method-color.method-qwen,.metric-track .method-qwen{background:#727e83}
.metric-groups{display:grid;gap:16px}
.metric-group{display:grid;gap:5px}
.metric-label{display:flex;align-items:baseline;justify-content:space-between;gap:10px}
.metric-label strong{font-size:11px;font-weight:500}
.metric-label small{color:var(--quiet);font-size:9px}
.metric-bar-row{display:grid;grid-template-columns:minmax(0,1fr) 60px;align-items:center;gap:8px}
.metric-track{height:8px;background:#273034;overflow:hidden}
.metric-track i{display:block;height:100%;min-width:1px}
.metric-bar-row b{text-align:right;color:#cbd5d7;font:400 9px 'IBM Plex Mono',monospace}
.evaluation-table-section{margin-bottom:30px;padding-bottom:24px;border-bottom:1px solid var(--line)}
.evaluation-table-section .section-heading,.method-explorer .section-heading{margin-bottom:8px}
.evaluation-table-section .section-heading h2,.method-explorer .section-heading h2{font-size:16px}
.evaluation-table-section .section-heading h2,.method-explorer .section-heading h2{font-size:16px}
.evaluation-table{font-variant-numeric:tabular-nums}
.evaluation-table td:first-child{font-weight:500;white-space:nowrap}
.evaluation-table td:first-child small{display:block;margin:2px 0 0 14px;color:var(--quiet);font-size:8px;font-weight:400}
.evaluation-headline-table{min-width:860px}
.method-dot{display:inline-block;width:6px;height:6px;margin-right:8px;border-radius:50%;vertical-align:1px}
.method-dot.method-features{background:var(--accent)}
.method-dot.method-cnn{background:#76a6c4}
.method-dot.method-opentslm{background:#d99a43}
.method-dot.method-qwen{background:#ba6c64}
.table-note{max-width:860px;margin-top:9px;color:var(--quiet);font-size:9px;line-height:1.55}
.plot-legend{display:flex;gap:14px;flex-wrap:wrap;padding:10px 0;color:var(--quiet);font-size:9px}
.plot-legend span{display:flex;align-items:center;gap:6px}
.plot-legend i{display:block;width:8px;height:8px}
.plot-primary{background:var(--accent)}
.plot-secondary{background:#76a6c4}
.plot-warning{background:#d99a43}
.grouped-plot-scroll{overflow-x:auto;padding-top:3px}
.grouped-plot{display:grid;grid-template-columns:repeat(4,minmax(68px,1fr));gap:8px;min-width:340px;height:230px;border-bottom:1px solid var(--line);background:repeating-linear-gradient(to bottom,transparent 0,transparent 53px,#2b3438 54px)}
.plot-method{display:grid;grid-template-rows:minmax(0,1fr) 27px;min-width:0}
.plot-bars{display:flex;align-items:flex-end;justify-content:center;gap:7px;min-height:0;padding:25px 5px 0}
.plot-bar-slot{display:flex;align-items:flex-end;width:min(27px,42%);height:100%}
.plot-bar-slot>i{position:relative;display:block;width:100%;min-height:2px}
.plot-bar-slot b{position:absolute;top:-15px;left:50%;transform:translateX(-50%);z-index:1;white-space:nowrap;color:#d7dfe1;font:500 8px 'IBM Plex Mono',monospace}
.plot-method>span{align-self:center;text-align:center;color:var(--quiet);font-size:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.method-explorer{margin-bottom:26px}
.method-tabs{display:flex;gap:18px;border-bottom:1px solid var(--line)}
.method-tabs button{min-height:39px;padding:0 1px;border:0;border-bottom:2px solid transparent;background:transparent;color:var(--quiet);font-size:11px}
.method-tabs button[aria-selected=true]{color:var(--accent);border-bottom-color:var(--accent)}
.method-detail{padding:17px 0;border-bottom:1px solid var(--line)}
.method-detail>header{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;margin-bottom:16px}
.method-detail h3{font-size:18px;font-weight:500}
.method-detail header p{color:var(--quiet);font-size:11px;margin-top:2px}
.method-detail header>span{border:1px solid #4b565a;padding:3px 7px;color:var(--quiet);font-size:9px}
.method-detail-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:28px}
.method-detail h4{margin:0 0 4px;color:var(--quiet);font-size:9px;font-weight:500;text-transform:uppercase;letter-spacing:.05em}
.method-detail h4:not(:first-child){margin-top:16px}
.method-detail p,.method-detail li{color:#c6d0d2;font-size:11px;line-height:1.6}
.method-detail ul,.method-detail ol{margin:0;padding-left:18px}
.method-detail li+li{margin-top:6px}
.method-reading{margin-top:17px;padding-top:14px;border-top:1px solid var(--line)}
.method-reading ul{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 26px}
.method-limit{display:flex;align-items:flex-start;gap:8px;margin-top:17px!important;padding-top:13px;border-top:1px solid var(--line);color:var(--quiet)!important}
.method-limit>svg{color:var(--quiet);margin-top:2px}
.method-limit span{display:grid;gap:2px}
.method-limit strong{color:#d4dcde;font-weight:500}
.evaluation-methodology{border-bottom:1px solid var(--line);padding-bottom:8px}
.evaluation-methodology>summary{cursor:pointer;padding:9px 0;color:#cad4d6;font-size:12px}
.evaluation-methodology p{max-width:900px;margin:8px 0;color:var(--quiet);font-size:11px;line-height:1.65}

@media(max-width:850px){
  .header-right{gap:6px}
  .header-right .btn{padding-inline:9px}
  .evaluation-chart-grid{grid-template-columns:1fr;gap:30px}
  .evaluation-summary{grid-template-columns:1fr!important}
  .evaluation-summary.evaluation-summary-four{grid-template-columns:repeat(2,minmax(0,1fr))!important}
  .evaluation-summary>div{padding:11px 0;border-right:0;border-bottom:1px solid var(--line)}
  .evaluation-summary.evaluation-summary-four>div:nth-child(odd){padding-right:12px;border-right:1px solid var(--line)}
  .evaluation-summary.evaluation-summary-four>div:nth-child(even){padding-left:12px}
  .evaluation-summary>div:last-child{border-bottom:0}
  .evaluation-summary dd{font-size:20px}
  .method-tabs{gap:13px;overflow-x:auto}
  .method-tabs button{white-space:nowrap;min-height:44px}
  .method-detail-grid{grid-template-columns:1fr;gap:18px}
  .method-reading ul{grid-template-columns:1fr}
}

.event-browser { min-height: 0; display: flex; flex-direction: column; }
.event-list { min-height: 0; overflow-y: auto; flex: 1; }
@media(max-width:850px) {
  .visual-tabs { height: auto; display: grid; grid-template-columns: repeat(3, 1fr); gap: 0 12px; padding-inline: 12px; }
  .visual-tabs > button { min-height: 40px; }
  .visual-tabs .replay-interval { grid-column: 1 / -1; margin: 0; justify-content: center; min-height: 32px; }
}
@media(max-width:850px) {
  .visual-robot .signals-panel { display: none; }
  .visual-robot .recording-context { flex: 1; min-height: 0; }
  .robot-joints { overflow-y: auto; }
}

/* Investigation comparison: a measured decision aid, separate from model output. */
.compare-current { margin: 0; padding: 9px 24px; border-bottom: 1px solid var(--line); flex-shrink: 0; justify-content: flex-start; }
.investigation-next { margin-top: 24px; border-top: 1px solid var(--line); }
.investigation-next > h3 { margin: 16px 0 7px; color: var(--quiet); font-size: 11px; font-weight: 500; letter-spacing: .05em; text-transform: uppercase; }
.investigation-actions { margin: 0; padding: 0; list-style: none; }
.investigation-actions li + li { border-top: 1px solid #30373b; }
.investigation-actions button { width: 100%; min-height: 38px; display: grid; grid-template-columns: 20px minmax(0,1fr) auto; align-items: center; gap: 9px; padding: 8px 2px; border: 0; background: transparent; color: #cbd5d7; text-align: left; }
.investigation-actions button:hover { color: var(--accent); }
.investigation-actions button > span { width: 18px; height: 18px; display: grid; place-items: center; border: 1px solid #496158; border-radius: 50%; color: var(--accent); font: 10px var(--mono); }
.investigation-actions button > strong { font-size: 12px; font-weight: 450; }
.custom-analysis { flex-shrink: 0; border-top: 1px solid var(--line); }
.custom-analysis > summary { min-height: 38px; display: flex; align-items: center; padding: 0 24px; color: var(--quiet); font-size: 11px; cursor: pointer; list-style: none; }
.custom-analysis > summary::-webkit-details-marker { display: none; }
.custom-analysis > summary::before { content: '+'; width: 18px; color: var(--accent); font: 14px var(--mono); }
.custom-analysis[open] > summary::before { content: '\2212'; }
.custom-analysis .composer { margin-top: 0; }
.visual-tabs { gap: 16px; padding-inline: 16px; }
.visual-tabs .replay-interval { font-size: 11px; white-space: nowrap; }
.comparison-panel { overflow-y: auto; min-height: 0; flex: 1; padding: 24px; overscroll-behavior: contain; }
.comparison-panel > header h2 { font-size: 22px; font-weight: 500; }
.comparison-panel > header p { color: var(--quiet); margin-top: 6px; line-height: 1.5; }
.comparison-selection { display: flex; gap: 12px; flex-wrap: wrap; justify-content: space-between; margin: 22px 0 14px; font-size: 12px; }
.comparison-selection strong { font-family: 'IBM Plex Mono', monospace; font-weight: 400; }
.reference-controls { padding-bottom: 12px; border-bottom: 1px solid var(--line); }
.reference-controls label { display: grid; gap: 6px; font-size: 12px; color: var(--quiet); }
.reference-controls select, .reference-controls input { color: var(--text); background: var(--panel); border: 1px solid var(--line); padding: 8px; border-radius: 4px; min-width: 0; width: 100%; }
.reference-controls > div { display: flex; gap: 12px; align-items: end; margin-top: 12px; }
.reference-controls > div label { max-width: 125px; }
.reference-controls > div > span { color: var(--quiet); font-size: 11px; padding-bottom: 10px; }
.reference-controls button { margin-left: auto; }
.reference-note, .comparison-empty { font-size: 12px; line-height: 1.6; color: var(--quiet); margin-block: 12px; }
.comparison-error { color: #edb6ab; font-size: 13px; margin-block: 14px; }
.comparison-finding { padding-block: 18px; }
.comparison-finding h3 { font-size: 16px; font-weight: 500; line-height: 1.5; }
.comparison-finding p { margin: 8px 0; font-size: 19px; font-variant-numeric: tabular-nums; }
.comparison-finding p strong { font-weight: 400; color: var(--accent); font-size: 15px; }
.comparison-finding > span { font-size: 11px; color: var(--quiet); }
.comparison-table-wrap { overflow-x: auto; }
.comparison-table { width: 100%; border-collapse: collapse; font-size: 12px; font-variant-numeric: tabular-nums; }
.comparison-table caption { text-align: left; color: var(--quiet); font-size: 11px; padding-bottom: 10px; }
.comparison-table th, .comparison-table td { padding: 8px; text-align: right; border-bottom: 1px solid var(--line); font-weight: 400; }
.comparison-table th:first-child { text-align: left; }
.comparison-table button { background: transparent; border: 0; padding: 3px 0; color: inherit; }
.comparison-table tr.selected { background: #25352f; }
.comparison-table tr.selected button { color: var(--accent); }
.comparison-plot { margin: 24px 0 0; }
.comparison-plot figcaption { display: flex; justify-content: space-between; gap: 10px; font-size: 12px; }
.comparison-plot figcaption strong { font-weight: 500; }
.comparison-plot figcaption span { display: flex; align-items: center; gap: 6px; color: var(--quiet); font-size: 11px; }
.comparison-plot i { width: 12px; height: 2px; background: var(--accent); }
.comparison-plot .reference-key { background: var(--amber); margin-left: 6px; }
.comparison-plot svg { width: 100%; display: block; margin-top: 10px; }
.comparison-axis { display: flex; justify-content: space-between; gap: 6px; font-size: 10px; color: var(--quiet); font-variant-numeric: tabular-nums; }
.comparison-plot p, .comparison-secondary { font-size: 11px; color: var(--quiet); line-height: 1.6; margin-top: 10px; }
.comparison-next { border-top: 1px solid var(--line); margin-top: 20px; padding-top: 18px; }
.comparison-next h3 { font-size: 14px; font-weight: 500; }
.comparison-next h3:not(:first-child) { margin-top: 20px; }
.comparison-next p, .comparison-method p { font-size: 12px; line-height: 1.7; color: var(--quiet); margin-top: 7px; max-width: 70ch; }
.comparison-next button { margin-top: 8px; }
.comparison-method { margin-block: 18px; font-size: 12px; color: var(--quiet); }
.comparison-method summary { cursor: pointer; }
.comparison-export { margin-bottom: 16px; }
@media(max-width:1100px) and (min-width:851px) { .visual-tabs { gap: 10px; padding-inline: 12px; flex-wrap: wrap; height: auto; min-height: 48px; } .visual-tabs > button { min-height: 38px; } }
@media(max-width:850px) { .visual-tabs { grid-template-columns: repeat(4, 1fr); gap: 0 8px; padding-inline: 10px; } .visual-tabs > button { font-size: 11px; } .comparison-panel { padding: 18px 14px; } .reference-controls > div { flex-wrap: wrap; } .reference-controls button { padding-inline: 10px; } .compare-current { padding-inline: 14px; } }

.reference-editor { font-size: 12px; color: var(--quiet); }
.reference-editor > summary { padding-block: 8px; cursor: pointer; color: var(--text); }
.reference-editor[open] > summary { margin-bottom: 8px; }
.comparison-finding > h3 { margin-top: 9px; }

/* Measured callouts attach to source samples, inspired by the supplied signal graphic. */
.annotated-comparison { margin-top: 12px; }
.annotated-comparison figcaption { align-items: center; margin-bottom: 22px; }
.annotated-comparison figcaption label { display: flex; gap: 9px; align-items: center; color: var(--quiet); }
.annotated-comparison select { background: var(--panel); border: 1px solid var(--line); border-radius: 4px; color: var(--text); padding: 7px 9px; }
.annotated-comparison svg { margin-top: 0; overflow: visible; }
.graph-callout { display: flex; flex-direction: column; gap: 5px; font-size: 12px; line-height: 1.5; }
.graph-callout strong { font-weight: 500; }
.graph-callout span { color: var(--text); font-variant-numeric: tabular-nums; }
.selected-callout { color: var(--accent); padding-left: 4%; }
.reference-callout { color: var(--amber); text-align: right; padding-right: 4%; }
.selected-wave, .reference-wave { fill: none; stroke-width: 1.6; vector-effect: non-scaling-stroke; }
.selected-wave { stroke: var(--accent); }
.reference-wave { stroke: var(--amber); stroke-dasharray: 5 4; }
.graph-leader { fill: none; stroke-width: 1; vector-effect: non-scaling-stroke; }
.selected-leader, .selected-point { stroke: var(--accent); }
.reference-leader, .reference-point { stroke: var(--amber); }
.reference-leader { stroke-dasharray: 3 3; }
.graph-point { fill: var(--panel); stroke-width: 1.5; vector-effect: non-scaling-stroke; }
.graph-scale { fill: #a2adb1; font-size: 13px; font-variant-numeric: tabular-nums; }
.annotated-comparison .comparison-axis { margin-top: 18px; border-top: 1px solid var(--line); padding-top: 10px; }
.comparison-all-joints { margin-top: 22px; font-size: 12px; }
.comparison-all-joints summary { cursor: pointer; padding-block: 10px; }
.comparison-all-joints[open] summary { margin-bottom: 10px; }
@media(max-width:850px) {
  .annotated-comparison figcaption { flex-wrap: wrap; gap: 10px; }
  .graph-scale { font-size: 18px; }
}

