/* Investigation-first layout: stable analysis alongside recorded motion. */
.app-shell { min-height: 640px; }
.app-header { height: 60px; padding-inline: 24px; }
.main-workspace { overflow: hidden; }
.demo-cases { display: flex; align-items: center; flex-shrink: 0; min-height: 64px; gap: 18px; padding: 12px 24px; border-bottom: 1px solid var(--line); background: #191d1f; }
.demo-cases label { display: flex; align-items: center; gap: 12px; color: var(--quiet); }
.demo-cases select { padding: 7px 10px; min-width: 218px; color: var(--text); background: var(--panel); border: 1px solid var(--line); border-radius: 4px; }
.case-source { position: relative; color: var(--quiet); font-size: 12px; margin-left: auto; }
.case-source { position: relative; color: var(--quiet); font-size: 12px; margin-left: auto; }
.case-source summary { cursor: pointer; padding: 6px 0; }
.case-source p { position: absolute; z-index: 30; right: 0; top: 32px; width: min(360px, 85vw); padding: 16px; background: var(--raised); border: 1px solid var(--line); line-height: 1.7; color: var(--text); }
.inspect-grid { grid-template-columns: minmax(360px, .85fr) minmax(480px, 1.25fr); }
.left-workspace { min-width: 0; overflow: hidden; }
