.visual-tabs button { background: none; border: 0; border-bottom: 2px solid transparent; padding: 0 1px; color: var(--quiet); }
.visual-tabs button[aria-pressed="true"] { color: var(--accent); border-bottom-color: var(--accent); }
.visual-workspace .recording-context { height: auto; min-height: 180px; flex: 1.2 1 0; }
.visual-workspace .signals-panel { height: auto; min-height: 200px; flex: 1 1 0; }
.visual-markers .recording-context { flex: 1; }
.visual-signals .signals-panel { flex: 1; min-height: 0; }
.visual-workspace .signal-strip { min-height: 0; }
.visual-workspace .recording-title { padding-block: 18px; }
.visual-workspace .explorer-body { padding-bottom: 20px; }
.visual-workspace .event-browser { width: 180px; }
.visual-workspace .panel-heading { height: 38px; }
.visual-workspace .robot-marker-note { display: none; }
.robot-caption { padding-inline: 20px; }
.robot-footer { padding-inline: 20px; }
.robot-joints p { display: none; }
