.model-input-status > div { display: grid; gap: 5px; }
.model-input-status strong { font-size: 14px; font-weight: 500; }
.model-input-status span { font-size: 12px; color: var(--quiet); }
.model-input-status .btn { min-height: 38px; padding-inline: 14px; }
.input-guidance { padding: 10px 24px; flex-shrink: 0; color: var(--quiet); font-size: 12px; }
