/* Investigation comparison: a measured decision aid, separate from model output. */
.compare-current { margin: 0; padding: 9px 24px; border-bottom: 1px solid var(--line); flex-shrink: 0; justify-content: flex-start; }
.investigation-next { margin-top: 24px; border-top: 1px solid var(--line); }
.investigation-next > h3 { margin: 16px 0 7px; color: var(--quiet); font-size: 11px; font-weight: 500; letter-spacing: .05em; text-transform: uppercase; }
.investigation-actions { margin: 0; padding: 0; list-style: none; }
.investigation-actions li + li { border-top: 1px solid #30373b; }
.investigation-actions button { width: 100%; min-height: 38px; display: grid; grid-template-columns: 20px minmax(0,1fr) auto; align-items: center; gap: 9px; padding: 8px 2px; border: 0; background: transparent; color: #cbd5d7; text-align: left; }
.investigation-actions button:hover { color: var(--accent); }
.investigation-actions button > span { width: 18px; height: 18px; display: grid; place-items: center; border: 1px solid #496158; border-radius: 50%; color: var(--accent); font: 10px var(--mono); }
.investigation-actions button > strong { font-size: 12px; font-weight: 450; }
.custom-analysis { flex-shrink: 0; border-top: 1px solid var(--line); }
.custom-analysis > summary { min-height: 38px; display: flex; align-items: center; padding: 0 24px; color: var(--quiet); font-size: 11px; cursor: pointer; list-style: none; }
.custom-analysis > summary::-webkit-details-marker { display: none; }
.custom-analysis > summary::before { content: '+'; width: 18px; color: var(--accent); font: 14px var(--mono); }
.custom-analysis[open] > summary::before { content: '\2212'; }
.custom-analysis .composer { margin-top: 0; }
.visual-tabs { gap: 16px; padding-inline: 16px; }
.visual-tabs .replay-interval { font-size: 11px; white-space: nowrap; }
.comparison-panel { overflow-y: auto; min-height: 0; flex: 1; padding: 24px; overscroll-behavior: contain; }
.comparison-panel > header h2 { font-size: 22px; font-weight: 500; }
.comparison-panel > header p { color: var(--quiet); margin-top: 6px; line-height: 1.5; }
.comparison-selection { display: flex; gap: 12px; flex-wrap: wrap; justify-content: space-between; margin: 22px 0 14px; font-size: 12px; }
.comparison-selection strong { font-family: 'IBM Plex Mono', monospace; font-weight: 400; }
.reference-controls { padding-bottom: 12px; border-bottom: 1px solid var(--line); }
.reference-controls label { display: grid; gap: 6px; font-size: 12px; color: var(--quiet); }
.reference-controls select, .reference-controls input { color: var(--text); background: var(--panel); border: 1px solid var(--line); padding: 8px; border-radius: 4px; min-width: 0; width: 100%; }
.reference-controls > div { display: flex; gap: 12px; align-items: end; margin-top: 12px; }
.reference-controls > div label { max-width: 125px; }
.reference-controls > div > span { color: var(--quiet); font-size: 11px; padding-bottom: 10px; }
.reference-controls button { margin-left: auto; }
.reference-note, .comparison-empty { font-size: 12px; line-height: 1.6; color: var(--quiet); margin-block: 12px; }
.comparison-error { color: #edb6ab; font-size: 13px; margin-block: 14px; }
.comparison-finding { padding-block: 18px; }
.comparison-finding h3 { font-size: 16px; font-weight: 500; line-height: 1.5; }
.comparison-finding p { margin: 8px 0; font-size: 19px; font-variant-numeric: tabular-nums; }
.comparison-finding p strong { font-weight: 400; color: var(--accent); font-size: 15px; }
.comparison-finding > span { font-size: 11px; color: var(--quiet); }
.comparison-table-wrap { overflow-x: auto; }
.comparison-table { width: 100%; border-collapse: collapse; font-size: 12px; font-variant-numeric: tabular-nums; }
.comparison-table caption { text-align: left; color: var(--quiet); font-size: 11px; padding-bottom: 10px; }
.comparison-table th, .comparison-table td { padding: 8px; text-align: right; border-bottom: 1px solid var(--line); font-weight: 400; }
.comparison-table th:first-child { text-align: left; }
.comparison-table button { background: transparent; border: 0; padding: 3px 0; color: inherit; }
.comparison-table tr.selected { background: #25352f; }
.comparison-table tr.selected button { color: var(--accent); }
.comparison-plot { margin: 24px 0 0; }
.comparison-plot figcaption { display: flex; justify-content: space-between; gap: 10px; font-size: 12px; }
.comparison-plot figcaption strong { font-weight: 500; }
.comparison-plot figcaption span { display: flex; align-items: center; gap: 6px; color: var(--quiet); font-size: 11px; }
.comparison-plot i { width: 12px; height: 2px; background: var(--accent); }
.comparison-plot .reference-key { background: var(--amber); margin-left: 6px; }
.comparison-plot svg { width: 100%; display: block; margin-top: 10px; }
.comparison-axis { display: flex; justify-content: space-between; gap: 6px; font-size: 10px; color: var(--quiet); font-variant-numeric: tabular-nums; }
.comparison-plot p, .comparison-secondary { font-size: 11px; color: var(--quiet); line-height: 1.6; margin-top: 10px; }
.comparison-next { border-top: 1px solid var(--line); margin-top: 20px; padding-top: 18px; }
.comparison-next h3 { font-size: 14px; font-weight: 500; }
.comparison-next h3:not(:first-child) { margin-top: 20px; }
.comparison-next p, .comparison-method p { font-size: 12px; line-height: 1.7; color: var(--quiet); margin-top: 7px; max-width: 70ch; }
.comparison-next button { margin-top: 8px; }
.comparison-method { margin-block: 18px; font-size: 12px; color: var(--quiet); }
.comparison-method summary { cursor: pointer; }
.comparison-export { margin-bottom: 16px; }
@media(max-width:1100px) and (min-width:851px) { .visual-tabs { gap: 10px; padding-inline: 12px; flex-wrap: wrap; height: auto; min-height: 48px; } .visual-tabs > button { min-height: 38px; } }
@media(max-width:850px) { .visual-tabs { grid-template-columns: repeat(4, 1fr); gap: 0 8px; padding-inline: 10px; } .visual-tabs > button { font-size: 11px; } .comparison-panel { padding: 18px 14px; } .reference-controls > div { flex-wrap: wrap; } .reference-controls button { padding-inline: 10px; } .compare-current { padding-inline: 14px; } }

.reference-editor { font-size: 12px; color: var(--quiet); }
.reference-editor > summary { padding-block: 8px; cursor: pointer; color: var(--text); }
.reference-editor[open] > summary { margin-bottom: 8px; }
.comparison-finding > h3 { margin-top: 9px; }

/* Measured callouts attach to source samples, inspired by the supplied signal graphic. */
.annotated-comparison { margin-top: 12px; }
.annotated-comparison figcaption { align-items: center; margin-bottom: 22px; }
.annotated-comparison figcaption label { display: flex; gap: 9px; align-items: center; color: var(--quiet); }
.annotated-comparison select { background: var(--panel); border: 1px solid var(--line); border-radius: 4px; color: var(--text); padding: 7px 9px; }
.annotated-comparison svg { margin-top: 0; overflow: visible; }
.graph-callout { display: flex; flex-direction: column; gap: 5px; font-size: 12px; line-height: 1.5; }
.graph-callout strong { font-weight: 500; }
.graph-callout span { color: var(--text); font-variant-numeric: tabular-nums; }
.selected-callout { color: var(--accent); padding-left: 4%; }
.reference-callout { color: var(--amber); text-align: right; padding-right: 4%; }
.selected-wave, .reference-wave { fill: none; stroke-width: 1.6; vector-effect: non-scaling-stroke; }
.selected-wave { stroke: var(--accent); }
.reference-wave { stroke: var(--amber); stroke-dasharray: 5 4; }
.graph-leader { fill: none; stroke-width: 1; vector-effect: non-scaling-stroke; }
.selected-leader, .selected-point { stroke: var(--accent); }
.reference-leader, .reference-point { stroke: var(--amber); }
.reference-leader { stroke-dasharray: 3 3; }
.graph-point { fill: var(--panel); stroke-width: 1.5; vector-effect: non-scaling-stroke; }
.graph-scale { fill: #a2adb1; font-size: 13px; font-variant-numeric: tabular-nums; }
.annotated-comparison .comparison-axis { margin-top: 18px; border-top: 1px solid var(--line); padding-top: 10px; }
.comparison-all-joints { margin-top: 22px; font-size: 12px; }
.comparison-all-joints summary { cursor: pointer; padding-block: 10px; }
.comparison-all-joints[open] summary { margin-bottom: 10px; }
@media(max-width:850px) {
  .annotated-comparison figcaption { flex-wrap: wrap; gap: 10px; }
  .graph-scale { font-size: 18px; }
}

